package com.golfhomes.society.controller; import com.golfhomes.society.model.Owner; import com.golfhomes.society.repository.OwnerRepository; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin/owners") @CrossOrigin(origins="http://localhost:5173") public class OwnerController { final OwnerRepository r; OwnerController(OwnerRepository r){this.r=r;} @GetMapping List<Owner> all(){return r.findAll();} @PostMapping Owner create(@RequestBody Owner x){return r.save(x);} @PutMapping("/{id}") Owner update(@PathVariable Long id,@RequestBody Owner x){x.setId(id);return r.save(x);} @DeleteMapping("/{id}") void delete(@PathVariable Long id){r.deleteById(id);} }
